mapper.select:
SELECT category, SUM(price) as total_amount, COUNT(*) as count
FROM `transaction`
WHERE wallet_id = #{walletId}
  AND DATE_FORMAT(txn_date, '%Y-%m') = #{month}
  AND txn_type = 'PAYMENT'
GROUP BY category

SELECT t.category, SUM(t.price) as total_amount, COUNT(*) as count
FROM `transaction` t
WHERE t.wallet_id = #{walletId}
  AND t.txn_type = 'PAYMENT'

    AND t.pet_id = #{petId}

GROUP BY t.category
